begin;
insert into public.ce_course3_resources(id,data) values
('course3_module7_pdf','{"base64": "", "sha256": "3193c5a128d50976ba8d28b78ef7cb8bb14369f8d812022428795b443fbe7a2d", "filename": "CE_HALO_Course3_Module07_Airway_Liability_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course3_module7_questions','[{"module_id": "course_3_module_7", "question_id": "course_3_module_7_q01", "question_number": 1, "stem": "In airway malpractice litigation, standard of care is best defined as:", "choice_a": "The level of care, skill, prudence, and judgment that a reasonably competent anesthesia professional would exercise under similar circumstances", "choice_b": "Whatever the individual CRNA believes is appropriate", "choice_c": "The absence of any complication", "choice_d": "Strict adherence to a single national protocol", "correct_choice": "a", "rationale": "Standard of care is not perfection; it is what a reasonably competent peer would do under similar circumstances. Airway cases evaluate foreseeability, alternatives, plan adaptation, and timeliness of rescue.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q02", "question_number": 2, "stem": "Which of the following is the most consistent recurring finding in closed-claims analyses of catastrophic airway cases?", "choice_a": "Failure to obtain a chest x-ray prior to induction", "choice_b": "Delayed transition to emergency front-of-neck access (eFONA) during cannot intubate, cannot oxygenate (CICO) events", "choice_c": "Failure to use a specific brand of endotracheal tube", "choice_d": "Failure to use total intravenous anesthesia", "correct_choice": "b", "rationale": "Joffe et al. (2019) and the broader ASA Closed Claims Project consistently identify delayed surgical airway during CICO as the most reliable finding in catastrophic airway claims.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q03", "question_number": 3, "stem": "Per the 2022 ASA Practice Guidelines for Management of the Difficult Airway, which of the following is emphasized as a core principle?", "choice_a": "Perform at least five direct laryngoscopy attempts before changing device", "choice_b": "Use only direct laryngoscopy as the primary technique", "choice_c": "Develop a strategy before induction, consider awake intubation when risk factors exist, maintain oxygenation, limit attempts, use cognitive aids, and ensure invasive airway rescue readiness", "choice_d": "Avoid supraglottic airways in all cases of difficult intubation", "correct_choice": "c", "rationale": "The 2022 ASA guidelines emphasize strategy, awake consideration, oxygenation, limited attempts, cognitive aids, and eFONA readiness (Apfelbaum et al., 2022).", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q04", "question_number": 4, "stem": "Within the Difficult Airway Society (DAS) framework for the unanticipated difficult airway, ''Plan D'' refers to:", "choice_a": "Placing a second supraglottic airway", "choice_b": "Waking the patient and rescheduling under regional anesthesia", "choice_c": "Awake fiberoptic intubation as a rescue technique", "choice_d": "Emergency front-of-neck access (eFONA) — cannot intubate, cannot oxygenate rescue via scalpel–bougie–tube cricothyrotomy", "correct_choice": "d", "rationale": "DAS Plan A = mask/intubation; Plan B = SGA; Plan C = mask ventilation and wake; Plan D = eFONA (scalpel–bougie–tube cricothyrotomy) for CICO.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q05", "question_number": 5, "stem": "A 58-year-old obese man with obstructive sleep apnea and a documented prior difficult intubation presents for elective cholecystectomy. A video laryngoscope is available in the OR. Which of the following most closely reflects the current (2024–2026) standard-of-care approach?", "choice_a": "Use video laryngoscopy as the first-choice device given identified risk factors and immediate availability, and document the rationale", "choice_b": "Rely solely on a supraglottic airway", "choice_c": "Cancel the case and refer to an anesthesiologist", "choice_d": "Attempt direct laryngoscopy first because it is the most familiar technique", "correct_choice": "a", "rationale": "Contemporary practice (2022 ASA guidelines; 2023 DEVICE trial; RCoA 2023) endorses VL as first-choice for anticipated difficulty when available. Documentation of the rationale is protective.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q06", "question_number": 6, "stem": "Which of the following preoperative airway documentation entries provides the greatest medico-legal protection for the CRNA?", "choice_a": "''Patient tolerated exam well''", "choice_b": "''Airway: Mallampati III, mouth opening 3 cm, thyromental distance 6 cm, obese (BMI 42) with OSA (STOP-Bang 6). Primary plan: VL with hyperangulated blade; backup: SGA and bougie; awake VL discussed with patient — declined given adequate anatomy; difficult airway cart at bedside.''", "choice_c": "''Airway WNL''", "choice_d": "''Airway checked''", "correct_choice": "b", "rationale": "Protective airway documentation is specific, includes risk factors, states primary and backup plans, and documents consideration and rationale for awake management when risk factors are present.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q07", "question_number": 7, "stem": "During a scheduled colonoscopy under MAC sedation, a morbidly obese patient with untreated OSA becomes cyanotic and unresponsive. The suite does not have capnography connected. Which of the following was the most significant departure from the standard of care?", "choice_a": "Providing MAC rather than general anesthesia", "choice_b": "Use of propofol for sedation", "choice_c": "Absence of continuous waveform capnography during moderate/deep sedation, which is required by the 2020 ASA Standards for Basic Anesthetic Monitoring", "choice_d": "Positioning the patient in the lateral decubitus position", "correct_choice": "c", "rationale": "Since 2011 (with reaffirmation through 2020), ASA Standards for Basic Anesthetic Monitoring require continuous waveform capnography during moderate and deep sedation. Its absence is a clear departure.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q08", "question_number": 8, "stem": "Which of the following is the preferred adult emergency front-of-neck access (eFONA) technique per the DAS and 2022 ASA guidelines?", "choice_a": "Retrograde intubation", "choice_b": "Needle cricothyrotomy with jet ventilation", "choice_c": "Percutaneous dilatational tracheostomy", "choice_d": "Scalpel–bougie–tube cricothyrotomy through the cricothyroid membrane", "correct_choice": "d", "rationale": "Scalpel–bougie–tube cricothyrotomy is the preferred adult eFONA technique per DAS 2015 and 2022 ASA guidelines. Needle cricothyrotomy has fallen out of favor in adults.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q09", "question_number": 9, "stem": "Awake fiberoptic intubation (AFOI) is most strongly indicated in which of the following scenarios?", "choice_a": "A patient with prior head-and-neck radiation, limited mouth opening, and progressive dysphagia scheduled for tumor debulking", "choice_b": "A patient with a well-controlled asthma exacerbation", "choice_c": "A healthy 25-year-old undergoing appendectomy", "choice_d": "An otherwise healthy patient with a BMI of 26", "correct_choice": "a", "rationale": "AFOI is indicated for anticipated difficult intubation when spontaneous ventilation preservation is essential — classic example is post-radiation head-and-neck cancer with airway distortion.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q10", "question_number": 10, "stem": "Which of the following is a legitimate indication for awake tracheostomy rather than awake fiberoptic intubation?", "choice_a": "Anxiety about awake procedures", "choice_b": "A large supraglottic tumor causing near-complete airway obstruction in which AFOI is unlikely to succeed and hostile anatomy contra-indicates asleep induction", "choice_c": "Uncomplicated obesity (BMI 32)", "choice_d": "Mild obstructive sleep apnea", "correct_choice": "b", "rationale": "Awake tracheostomy is reserved for patients in whom AFOI is unlikely to succeed — large supraglottic tumors, near-complete obstruction, or hostile anatomy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q11", "question_number": 11, "stem": "Dental damage claims following anesthesia are best minimized by which combination of practices?", "choice_a": "Skipping the dental exam to save time", "choice_b": "Avoiding intubation in all patients with crowns or bridges", "choice_c": "Preoperative dental documentation, dental guard when indicated, gentle laryngoscopy technique, video laryngoscopy in poor-view patients, and prompt disclosure with referral if injury occurs", "choice_d": "Using only nasal intubation", "correct_choice": "c", "rationale": "Prevention is the combination of preoperative documentation, protective devices when indicated, gentle technique, VL for difficult views, and disclosure/referral if injury occurs.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q12", "question_number": 12, "stem": "A patient undergoing prolonged prone spine surgery received large-volume fluid resuscitation. Prior to extubation, which of the following is most appropriate?", "choice_a": "Immediate extubation to shorten OR time", "choice_b": "Deep extubation to reduce cough", "choice_c": "Extubation in the PACU without further assessment", "choice_d": "Structured DAS-based at-risk extubation plan: confirm reversal with TOFR ≥ 0.9, perform cuff-leak test, ensure reintubation equipment and personnel present, and consider airway-exchange catheter", "correct_choice": "d", "rationale": "Prone position and large fluid resuscitation predict airway edema. DAS 2024 extubation guidelines recommend a structured at-risk plan including cuff-leak testing and reintubation readiness.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q13", "question_number": 13, "stem": "Which of the following best describes the ''physiologically difficult airway''?", "choice_a": "A patient with normal airway anatomy in whom shock, hypoxemia, metabolic acidosis, pulmonary hypertension, or right-heart failure makes induction and positive-pressure ventilation dangerous", "choice_b": "A patient with a history of asthma", "choice_c": "An airway with abnormal anatomy", "choice_d": "An airway that requires video laryngoscopy", "correct_choice": "a", "rationale": "The physiologically difficult airway refers to anatomically normal patients whose physiology creates peri-intubation risk — shock, severe hypoxemia, acidosis, pulmonary hypertension, right-heart failure.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q14", "question_number": 14, "stem": "Which action is most consistent with avoiding ''fixation error'' during a difficult airway?", "choice_a": "Repositioning the patient repeatedly without changing device", "choice_b": "Limiting repeated attempts with the same operator/device/technique, explicitly calling for help, transitioning to alternate devices (SGA, VL), and declaring CICO when oxygenation cannot be maintained", "choice_c": "Continuing direct laryngoscopy attempts until intubation is successful", "choice_d": "Adding more anesthetic to relax the patient''s airway", "correct_choice": "b", "rationale": "Fixation error — repeated attempts without a change of operator, device, or technique — is a recurring closed-claims theme. Cognitive aids and structured escalation prevent it.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q15", "question_number": 15, "stem": "Under the 2023 ASA Practice Guidelines for monitoring and antagonism of neuromuscular blockade, which train-of-four ratio threshold should be met prior to extubation?", "choice_a": "≥ 0.4", "choice_b": "≥ 0.7", "choice_c": "≥ 0.9", "choice_d": "Extubation may proceed without TOFR measurement", "correct_choice": "c", "rationale": "The 2023 ASA guidelines recommend quantitative neuromuscular monitoring and a TOFR ≥ 0.9 prior to extubation to avoid residual neuromuscular blockade.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q16", "question_number": 16, "stem": "Which of the following documentation errors is most likely to shift a malpractice case decisively against the CRNA?", "choice_a": "Documenting time-stamped drug administration", "choice_b": "Documenting waveform capnography confirmation of tube placement", "choice_c": "Using standard airway-assessment shorthand", "choice_d": "Making a post-event chart entry that is not clearly marked as an addendum and is inconsistent with monitor-recorded vital signs", "correct_choice": "d", "rationale": "Late or altered entries after an adverse event — particularly when inconsistent with monitor data — may constitute spoliation of evidence and destroy the CRNA''s credibility.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q17", "question_number": 17, "stem": "Which of the following patient-related preoperative factors are included in the Kheterpal predictors of difficult mask ventilation?", "choice_a": "Age > 55, BMI > 30, beard, edentulism, snoring history, Mallampati III–IV, limited jaw protrusion, and neck radiation", "choice_b": "Serum sodium and potassium", "choice_c": "Blood type and Rh factor", "choice_d": "Preoperative hemoglobin only", "correct_choice": "a", "rationale": "Kheterpal et al. (2006, 2013) identified age > 55, BMI > 30, beard, edentulism, snoring, Mallampati III–IV, limited jaw protrusion, and neck radiation as difficult-mask-ventilation predictors.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q18", "question_number": 18, "stem": "A CRNA is providing MAC for interventional radiology and the proceduralist requests continued sedation despite the patient showing airway compromise. The most appropriate action is:", "choice_a": "Give reversal only if the patient is fully awake", "choice_b": "Pause or terminate the procedure to secure the airway and stabilize the patient — the CRNA retains authority and obligation to interrupt for airway or physiologic compromise regardless of procedural pressure", "choice_c": "Ask the proceduralist to make the decision", "choice_d": "Continue sedation to maintain schedule", "correct_choice": "b", "rationale": "The anesthesia provider — CRNA or physician — retains authority and obligation to pause or terminate a procedure for airway or physiologic compromise. This should be pre-briefed with the procedural team.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q19", "question_number": 19, "stem": "Which cognitive aid is built around three ''lifelines'' (face mask, supraglottic airway, tracheal tube) and a central ''CICO Zone'' that mandates eFONA?", "choice_a": "The DAS Plan A–D framework", "choice_b": "The ASA Difficult Airway Algorithm", "choice_c": "The Vortex Approach", "choice_d": "The NAP4 report", "correct_choice": "c", "rationale": "The Vortex Approach (Chrimes, 2016; updated 2024) uses three ''lifelines'' and a central CICO zone as a real-time team cognitive aid; it is complementary to the ASA and DAS algorithms.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q20", "question_number": 20, "stem": "A patient with anticipated difficult airway based on prior documented difficult intubation is scheduled for elective surgery. The CRNA does not mention awake intubation in the preoperative note or discuss it with the patient. Induction is performed and multiple attempts result in hypoxic injury. The strongest medico-legal criticism will most likely focus on:", "choice_a": "Choice of muscle relaxant", "choice_b": "Room temperature during induction", "choice_c": "Choice of induction drug", "choice_d": "Failure to document consideration of, and rationale for or against, awake tracheal intubation in a patient with clear predictors — a departure from the 2020 DAS awake tracheal intubation guidelines and the 2022 ASA difficult airway guidelines", "correct_choice": "d", "rationale": "Failure to consider and document awake management in a patient with clear predictors is a common closed-claims criticism and a departure from current DAS/ASA guidelines.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q21", "question_number": 21, "stem": "After a difficult airway event, which of the following is the most protective post-event action for both the patient and the CRNA?", "choice_a": "Enter a persistent difficult airway alert into the EHR, provide the patient with a written record of the event (e.g., MedicAlert or DAS Airway Alert card), communicate to primary care, and file an institutional event report per policy", "choice_b": "Delete the difficult airway alert to avoid alarming future providers", "choice_c": "Wait until the next admission to decide whether to document", "choice_d": "Only tell the anesthesiology department verbally", "correct_choice": "a", "rationale": "Persistent EHR airway alerts, written patient records, primary care communication, and institutional reporting protect future patient safety and demonstrate a defensible post-event process.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q22", "question_number": 22, "stem": "Which of the following is a growing 2023–2025 concern in preoperative airway/aspiration risk assessment that CRNAs should document?", "choice_a": "Use of over-the-counter multivitamins", "choice_b": "Use of glucagon-like peptide-1 (GLP-1) receptor agonists (e.g., semaglutide, tirzepatide), which delay gastric emptying and per ASA 2023 consensus-based guidance affect aspiration risk and fasting recommendations", "choice_c": "Use of a home nebulizer for asthma", "choice_d": "Recent influenza vaccination", "correct_choice": "b", "rationale": "ASA 2023 consensus-based guidance addresses preoperative management of GLP-1 receptor agonists due to delayed gastric emptying and aspiration concerns. CRNAs should screen and document.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q23", "question_number": 23, "stem": "Regarding ''guidelines'' such as the 2022 ASA and 2015 DAS airway algorithms, which of the following is most accurate?", "choice_a": "They apply only to anesthesiologists, not CRNAs", "choice_b": "They are legally binding federal regulations", "choice_c": "They are typically described as recommendations rather than binding legal rules, but they strongly influence expert testimony and institutional policy; substantial deviation without documented justification is difficult to defend", "choice_d": "They have no medico-legal relevance", "correct_choice": "c", "rationale": "Guidelines are recommendations, not federal regulations, but they shape expert testimony and institutional standards. Undocumented substantial deviation is a common malpractice vulnerability.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q24", "question_number": 24, "stem": "Which of the following best characterizes the medico-legal significance of ''closed-claims'' data such as the ASA Closed Claims Project?", "choice_a": "They provide the true incidence of adverse events in anesthesia", "choice_b": "They are legally binding case law", "choice_c": "They are used to license CRNAs", "choice_d": "They are not incidence studies but reveal recurring themes in resolved claims — enriched for severe outcomes — that identify preventable patterns and shape risk-management practice", "correct_choice": "d", "rationale": "Closed-claims data are not incidence studies; they reveal recurring, enriched patterns of severe outcomes that inform risk management and expert testimony.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_3_module_7", "question_id": "course_3_module_7_q25", "question_number": 25, "stem": "During an unanticipated difficult intubation, SpO₂ falls to 60% despite three intubation attempts and two supraglottic airway attempts with inadequate ventilation. The next most appropriate action is to:", "choice_a": "Declare cannot intubate, cannot oxygenate (CICO), continue oxygenation attempts, and immediately move to scalpel–bougie–tube cricothyrotomy", "choice_b": "Attempt one more direct laryngoscopy with a different blade", "choice_c": "Wake the patient", "choice_d": "Give additional muscle relaxant and try again", "correct_choice": "a", "rationale": "Failure of mask, SGA, and intubation with falling SpO₂ is the definition of CICO. The 2022 ASA and DAS guidelines mandate declaration and eFONA (scalpel–bougie–tube cricothyrotomy) without further delay.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course3_resources where id='course3_module7_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course3_catalog where id='1047243'),'Course must remain staged';
end $$;
commit;